use super::empty::Empty;
use super::space::Space;
use super::{Join, Request};
use crate::index::Index;
use crate::slot::Slot;
use std::task::Poll;

enum State {
    Empty(Empty),
    Active(Box<Join>),
}

pub(crate) struct Session(State);

impl Session {
    #[cfg(test)]
    pub fn new(
        pattern: std::sync::Arc<Vec<Vec<crate::term::Term>>>,
        index: &Index,
        frame: usize,
    ) -> Self {
        Self(State::Active(Box::new(Join::new(pattern, index, frame))))
    }

    pub fn planned(request: Request<'_>) -> Self {
        let index = request.index;
        let space = Space::planned(request);
        if space.vacant() {
            return Self(State::Empty(space.release()));
        }
        Self(State::Active(Box::new(Join::construct(space, index))))
    }

    pub fn waiting(&self) -> usize {
        match &self.0 {
            State::Empty(_) => 0,
            State::Active(join) => join.waiting(),
        }
    }

    pub fn skip(&mut self, maximum: usize) -> usize {
        match &mut self.0 {
            State::Empty(_) => 0,
            State::Active(join) => join.skip(maximum),
        }
    }

    pub fn update(&mut self, index: &Index) -> bool {
        let empty = match &mut self.0 {
            State::Empty(empty) => empty,
            State::Active(join) => return join.update(index),
        };
        if !empty.affected(index) {
            return false;
        }
        self.0 = State::Active(Box::new(empty.activate(index)));
        true
    }

    pub fn reset(&mut self, index: &Index) {
        if let State::Active(join) = &mut self.0 {
            join.reset(index);
        }
    }

    pub fn viable(&self) -> bool {
        match &self.0 {
            State::Empty(_) => false,
            State::Active(join) => join.viable(),
        }
    }

    pub fn frame(&self) -> usize {
        match &self.0 {
            State::Empty(empty) => empty.frame,
            State::Active(join) => join.frame(),
        }
    }

    pub fn step(&mut self, index: &Index) -> Poll<Option<Vec<Slot>>> {
        match &mut self.0 {
            State::Empty(_) => Poll::Ready(None),
            State::Active(join) => join.step(index),
        }
    }

    pub fn evict(&mut self) {
        if let State::Active(join) = &mut self.0 {
            join.evict();
        }
    }

    pub fn retained(&self) -> usize {
        match &self.0 {
            State::Empty(empty) => empty.retained(),
            State::Active(join) => join.retained(),
        }
    }
}

