use super::query::Query;
use super::space::Space;
use super::{Join, Store};
use crate::index::Index;
use std::sync::Arc;

pub(super) struct Empty {
    pub frame: usize,
    pub query: Query,
    pub store: Option<Arc<Store>>,
    pub shared: Option<Arc<crate::preparation::Store>>,
}

impl Empty {
    pub fn affected(&self, index: &Index) -> bool {
        index.insertion.iter().any(|&site| {
            index.state.world[index.world(site)].frame == self.frame
                && (0..self.query.count()).any(|position| self.query.matches(position, index, site))
        })
    }

    pub fn activate(&self, index: &Index) -> Join {
        let mut join = Join::construct(Space::restore(self), index);
        assert!(join.update(index));
        join
    }

    pub fn retained(&self) -> usize {
        self.query.retained() + self.query.count() * 4
    }
}

